import {clone,uid} from './core.js';
export const blendModes=['normal','multiply','screen','overlay','darken','lighten'];
export function linearGradient(o,start='#ffffff',end='#252a29'){o.gradient={type:'linear',x1:0,y1:.5,x2:1,y2:.5,stops:[{offset:0,color:start,opacity:1},{offset:1,color:end,opacity:1}]};return o.gradient;}
export function gradientDefinition(o,escape){const g=o.gradient;if(!g)return '';const stops=g.stops.map(s=>`<stop offset="${s.offset*100}%" stop-color="${escape(s.color)}" stop-opacity="${s.opacity??1}"/>`).join('');return g.type==='radial'?`<radialGradient id="gradient-${escape(o.id)}" cx="${g.x1}" cy="${g.y1}" r="${Math.hypot(g.x2-g.x1,g.y2-g.y1)}">${stops}</radialGradient>`:`<linearGradient id="gradient-${escape(o.id)}" x1="${g.x1}" y1="${g.y1}" x2="${g.x2}" y2="${g.y2}">${stops}</linearGradient>`;}
export function validateAppearance(o){for(const paint of [o.fill,o.stroke])if(paint!==undefined&&(typeof paint!=='string'||/[<>"\'\\]|url\s*\(|expression\s*\(/i.test(paint)))throw Error('Pintura inválida.');if(o.gradient){const g=o.gradient;if(!['linear','radial'].includes(g.type)||['x1','y1','x2','y2'].some(k=>!Number.isFinite(g[k]))||!Array.isArray(g.stops)||g.stops.length<2||g.stops.length>64||g.stops.some(s=>!Number.isFinite(s.offset)||s.offset<0||s.offset>1||!/^#[\da-f]{6}$/i.test(s.color)||!Number.isFinite(s.opacity??1)||(s.opacity??1)<0||(s.opacity??1)>1))throw Error('Degradado inválido.');}if(o.blendMode&&!blendModes.includes(o.blendMode))throw Error('Modo de fusión inválido.');if(o.lineCap&&!['butt','round','square'].includes(o.lineCap)||o.lineJoin&&!['miter','round','bevel'].includes(o.lineJoin))throw Error('Terminación de línea inválida.');return o;}
